createComposer({
  labels,
  contextLabels,
  context: referencias,
  onRemoveContext: (item) => tirar(item.id),
});

basicCode.react:
import { Composer } from "@/components/ui/composer";

<Composer
  labels={labels}
  contextLabels={contextLabels}
  context={referencias}
  onRemoveContext={(item) => tirar(item.id)}
/>

withAutomaticCode.web:
// Referência é o que já existe: nada sobe, nada espera, nada falha.
{ id: 'c1', label: 'relatorio.ts', kind: 'selection', detail: 'linhas 12–48' }

// Automático é o que entrou sem ninguém pedir. Ele não ganha botão de
// remover: voltaria na próxima pergunta.
{ id: 'c2', label: 'Painel de medidas', kind: 'page', automatic: true }

extensibilityCode.web:
// O item é DADO, e o componente não sabe o que ele significa.
// O que faz um item entrar sozinho, o quanto ele abrange e o que acontece ao
// tirá-lo é de quem monta a pergunta.
{
  id: 'c1',
  label: 'relatorio.ts',   // o nome curto; o caminho inteiro não cabe
  kind: 'selection',       // decide o ícone e a palavra do nome acessível
  detail: 'linhas 12–48',  // o recorte, quando o item é um pedaço
  automatic: false,        // verdadeiro tira o botão e acrescenta a marca
}

customizationCode.web:
.nds-composer-context-item {
  max-inline-size: 20rem;
}

/* A moldura tracejada do automático é REFORÇO, e não a pista: a marca escrita
   ao lado é o que descreve o estado. Cor e traço sozinhos não descrevem. */
.nds-composer-context-item[data-automatic="true"] {
  border-style: dashed;
}

